package com.rikkeibank.notification.controller; import com.rikkeibank.notification.service.NotificationEventStore; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; @RestController @RequestMapping("/api/notifications") public class NotificationController{private final NotificationEventStore store;public NotificationController(NotificationEventStore s){store=s;}@GetMapping("/events") public Flux<NotificationEventStore.ReceivedEvent> events(){return store.stream();}}